//! OpenSSH integration, written by `massrelay install` and removed by `massrelay uninstall`
//! alone. The running service never changes the account's SSH configuration.
//!
//! The account's `~/.ssh/config` gets one `Include massrelay.d/*.conf` before its other
//! directives so an included host's explicit trust settings take precedence. Each profile has one generated file in `massrelay.d` that includes
//! `ssh-client.conf` from its private directory. The install creates that file empty; its
//! existence is what asks the runtime to fill it in.
//!
//! OpenSSH reads the fragments before the rest of the user's configuration and keeps the first
//! value it finds, so `ssh-client.conf` must put every setting under a `Host` line.
//!
//! Nothing is written through a link, no permission is changed to pass a check, and no file
//! the install did not generate is overwritten. The platform's file module holds the checks.
//!
//! An uninstall removes only what it can show is MassRelay's: the profile's generated file
//! in `massrelay.d` if unchanged and, once no file there is left to include, the two lines
//! added to `~/.ssh/config`. That unchanged file also shows that the install made the
//! profile's `ssh-client.conf`, which is removed if it is empty or exactly what the runtime
//! recorded writing in `ssh-client-published.sha256`; a record that matches goes with it.
//! Anything else stays, with the reason shown. The alias reservations always stay, so that
//! an alias given out before an uninstall cannot name another device after a later install.

use std::collections::BTreeMap;
use std::io::Write as _;
use std::path::{Path, PathBuf};

use anyhow::{Context, Result, bail, ensure};
use sha2::{Digest, Sha256};

#[cfg(windows)]
use crate::windows_service::ssh_files as files;
#[cfg(unix)]
mod unix;
#[cfg(unix)]
use unix as files;

use crate::private::cli;
use files::{Account, Found};

/// The OpenSSH configuration a profile's runtime writes, in the private profile directory.
pub const CLIENT_CONFIG: &str = "ssh-client.conf";
pub const CLIENT_STATE: &str = "ssh-client.json";
/// Beside them, the runtime's record of the `CLIENT_CONFIG` it last wrote: its SHA-256 in
/// lowercase hexadecimal and a newline, in a private file.
pub const CLIENT_RECORD: &str = "ssh-client-published.sha256";
/// The directory beside `~/.ssh/config` holding one generated file for each profile.
const FRAGMENTS: &str = "massrelay.d";
/// In that directory, the namespace reserved for each profile there has ever been.
const LEDGER: &str = ".namespaces.json";
const LOCK: &str = ".lock";
/// Relative, as OpenSSH reads a path under `~/.ssh` in the user's configuration. It finds
/// that `~` through `HOME`, so an `ssh` run with another `HOME` does not see the profiles.
const PATTERN: &str = "massrelay.d/*.conf";
const GENERATED: &str = "# Generated by massrelay install\n";
/// The comment above the added `Include`, which marks the pair as the install's.
const MARKER: &str = "# Added by massrelay install";
const BOM: &[u8] = b"\xef\xbb\xbf";
/// How often a file that changes while it is being replaced is read again.
const ATTEMPTS: usize = 3;

/// `path` as the installed service and the generated SSH files name it.
pub fn canonical(path: &Path) -> Result<PathBuf> {
    files::canonical(path)
}

/// What `register` would write for the profile in `state_dir`, changing nothing.
pub fn describe_register(state_dir: &Path) -> Result<String> {
    let home = Account::current()?.home()?;
    let profile = state_dir.join(cli::DIR_NAME);
    let client = profile.join(CLIENT_CONFIG);
    let (name, _) = fragment(&client)?;
    let ssh = home.join(".ssh");
    let fragments = ssh.join(FRAGMENTS);
    Ok(format!(
        "add 'Include {PATTERN}' above the other directives, if missing: {}\n\
         write this profile's include: {}\n\
         reserve its alias namespace: {}\n\
         create if missing, for the service to fill in: {}\n\
         create if missing, to keep each alias with one device: {}\n\
         create these directories and a lock file in the second, if missing: {}, {}",
        ssh.join("config").display(),
        fragments.join(name).display(),
        fragments.join(LEDGER).display(),
        client.display(),
        profile.join(CLIENT_STATE).display(),
        ssh.display(),
        fragments.display(),
    ))
}

/// Connect this account's OpenSSH to the profile in `state_dir`, the canonical path its
/// service was just installed for.
pub fn register(state_dir: &Path) -> Result<()> {
    let config = check_openssh()
        .and_then(|()| Account::current())
        .and_then(|account| integrate(&account, &account.home()?, state_dir))
        .context(
            "the background service is installed and running, but this account's OpenSSH \
             aliases are not set up for it. Correct this and run 'massrelay install' again",
        )?;
    crate::update::say(format!("SSH config      {}", config.display()));
    Ok(())
}

/// Managed entries disable the user's fallback host-key command explicitly. Never make an
/// older system client parse a keyword it cannot recognize, even for an unrelated host.
fn check_openssh() -> Result<()> {
    let output = std::process::Command::new(crate::private::ssh::openssh("ssh")?)
        .arg("-V")
        .output()
        .context("check the system OpenSSH client")?;
    ensure!(
        output.status.success(),
        "could not check the system OpenSSH version"
    );
    let text = String::from_utf8_lossy(&output.stderr);
    let version = text
        .trim_start()
        .strip_prefix("OpenSSH_for_Windows_")
        .or_else(|| text.trim_start().strip_prefix("OpenSSH_"));
    let supported = version
        .and_then(|version| version.split_once('.'))
        .and_then(|(major, minor)| {
            Some((
                major.parse::<u32>().ok()?,
                minor
                    .split(|c: char| !c.is_ascii_digit())
                    .next()?
                    .parse::<u32>()
                    .ok()?,
            ))
        })
        .is_some_and(|version| version >= (8, 5));
    ensure!(
        supported,
        "managed SSH config requires OpenSSH 8.5 or later"
    );
    Ok(())
}

/// `register` for the account whose home directory is `home`. Returns its SSH configuration.
pub(crate) fn integrate(account: &Account, home: &Path, state_dir: &Path) -> Result<PathBuf> {
    ensure!(
        files::canonical(state_dir)? == state_dir,
        "{} was replaced while it was being installed",
        state_dir.display()
    );
    let profile = state_dir.join(cli::DIR_NAME);
    account.profile_directory(&profile)?;
    let client = profile.join(CLIENT_CONFIG);
    let (name, fragment) = fragment(&client)?;
    // An existing file that must not be included stops the install before anything changes.
    if let Some(found) = account.read(&client)? {
        account.check_client(&client, &found)?;
    }

    account.home_directory(home)?;
    let ssh = home.join(".ssh");
    account.ssh_directory(&ssh)?;
    let fragments = ssh.join(FRAGMENTS);
    account.fragment_directory(&fragments)?;
    let _lock = account.lock(&fragments.join(LOCK))?;

    let target = fragments.join(name);
    let generated = |found: &Found| -> Result<()> {
        account.check_fragment(&target, found)?;
        ensure!(
            found.contents.starts_with(GENERATED.as_bytes()),
            "{} was not generated by massrelay install; it was not changed",
            target.display()
        );
        Ok(())
    };
    let existing = account.read(&target)?;
    if let Some(found) = &existing {
        generated(found)?;
    }
    let namespace = reserve_namespace(account, &fragments, &target)?;
    let state = profile.join(CLIENT_STATE);
    update(account, &state, |found| match found {
        Some(found) => {
            account.check_client(&state, found)?;
            let saved: serde_json::Value = serde_json::from_slice(&found.contents)
                .context("read the profile's SSH alias reservations")?;
            ensure!(
                saved.get("namespace").and_then(serde_json::Value::as_u64) == Some(namespace),
                "the profile's SSH alias namespace has changed"
            );
            Ok(None)
        }
        None => {
            ensure!(
                existing.is_none(),
                "the profile's SSH alias reservations are missing"
            );
            Ok(Some(serde_json::to_vec(&serde_json::json!({
                "namespace": namespace,
                "names": {},
                "hosts": {},
            }))?))
        }
    })?;

    let config = ssh.join("config");
    update(account, &config, |found| match found {
        Some(found) => match include_position(&found.contents, &ssh) {
            IncludePosition::First => Ok(None),
            IncludePosition::Later => {
                bail!("the MassRelay Include follows another global SSH directive")
            }
            IncludePosition::Absent => with_include(&found.contents).map(Some),
        },
        None => with_include(b"").map(Some),
    })
    // Said for a configuration this will not write, such as a link into a dotfile tree.
    .with_context(|| {
        format!(
            "put 'Include {PATTERN}' before any other directive in {}",
            config.display()
        )
    })?;
    update(account, &target, |found| {
        if let Some(found) = found {
            generated(found)?;
            if found.contents == fragment.as_bytes() {
                return Ok(None);
            }
        }
        Ok(Some(fragment.clone().into_bytes()))
    })?;
    // Last: the runtime writes the file once it exists, and by now ssh reads it.
    update(account, &client, |found| match found {
        Some(found) => account.check_client(&client, found).map(|()| None),
        None => Ok(Some(Vec::new())),
    })?;
    Ok(config)
}

/// The install lock makes allocations account-wide and durable. Only the first profile
/// can use bare peer names. Other profiles reserve a disjoint numeric suffix.
fn reserve_namespace(account: &Account, dir: &Path, profile: &Path) -> Result<u64> {
    let ledger = dir.join(LEDGER);
    let name = profile
        .file_name()
        .and_then(|name| name.to_str())
        .context("invalid profile name")?;
    let mut namespace = None;
    update(account, &ledger, |found| {
        let mut reservations: BTreeMap<String, u64> = match found {
            Some(found) => {
                account.check_fragment(&ledger, found)?;
                serde_json::from_slice(&found.contents).context("read SSH profile namespaces")?
            }
            None => BTreeMap::new(),
        };
        for entry in std::fs::read_dir(dir)? {
            let path = entry?.path();
            if path.extension().is_some_and(|ext| ext == "conf") {
                let name = path.file_name().and_then(|name| name.to_str());
                ensure!(
                    name.is_some_and(|name| reservations.contains_key(name)),
                    "the SSH profile namespace ledger does not cover {}",
                    path.display()
                );
            }
        }
        let unique: std::collections::BTreeSet<_> = reservations.values().copied().collect();
        ensure!(
            !unique.contains(&0) && unique.len() == reservations.len(),
            "invalid SSH profile namespace ledger"
        );
        if let Some(assigned) = reservations.get(name) {
            namespace = Some(*assigned);
            return Ok(None);
        }
        let next = reservations
            .values()
            .max()
            .copied()
            .unwrap_or(0)
            .checked_add(1)
            .context("SSH profile namespace exhausted")?;
        namespace = Some(next);
        reservations.insert(name.to_owned(), next);
        Ok(Some(serde_json::to_vec(&reservations)?))
    })?;
    namespace.context("no SSH profile namespace was reserved")
}

/// Bring a file to what `change` makes of it, where `None` leaves it as it is. A file that
/// changes or appears meanwhile is read again, never overwritten with an older reading.
fn update(
    account: &Account,
    path: &Path,
    mut change: impl FnMut(Option<&Found>) -> Result<Option<Vec<u8>>>,
) -> Result<()> {
    for _ in 0..ATTEMPTS {
        let found = account.read(path)?;
        let Some(contents) = change(found.as_ref())? else {
            return Ok(());
        };
        let written = match &found {
            Some(found) => account.replace(path, found, &contents)?,
            None => account.create(path, &contents)?,
        };
        if written {
            return Ok(());
        }
    }
    bail!(
        "{} kept changing while it was being updated",
        path.display()
    )
}

/// Delete the file at `path` while `check` accepts it. A file that changes meanwhile is
/// checked again.
fn delete(account: &Account, path: &Path, check: impl Fn(&Found) -> Result<()>) -> Result<()> {
    for _ in 0..ATTEMPTS {
        let Some(found) = account.read(path)? else {
            return Ok(());
        };
        check(&found)?;
        if account.remove(path, &found)? {
            return Ok(());
        }
    }
    bail!(
        "{} kept changing while it was being removed",
        path.display()
    )
}

/// What an uninstall does about one file.
enum Fate {
    /// Not there, or nothing in it is the install's.
    Absent,
    Remove,
    Keep(String),
}

impl Fate {
    /// Judge the file at `path`, which is removable only if it passes `check`. One that
    /// cannot be read or fails is kept.
    fn of(account: &Account, path: &Path, check: impl FnOnce(&Found) -> Result<()>) -> Self {
        match account.read(path) {
            Ok(None) => Self::Absent,
            Ok(Some(found)) => match check(&found) {
                Ok(()) => Self::Remove,
                Err(error) => Self::Keep(format!("{error:#}")),
            },
            Err(error) => Self::Keep(format!("{error:#}")),
        }
    }
}

/// The files of one profile's OpenSSH setup, and the checks an uninstall makes of them.
struct Setup {
    account: Account,
    home: PathBuf,
    profile: PathBuf,
    /// The generated fragment's path and exact contents. `None` if the profile's path is
    /// one OpenSSH cannot include, for which the install writes none.
    fragment: Option<(PathBuf, String)>,
}

impl Setup {
    fn new(account: Account, home: &Path, state_dir: &Path) -> Self {
        let profile = state_dir.join(cli::DIR_NAME);
        let fragment = fragment(&profile.join(CLIENT_CONFIG))
            .ok()
            .map(|(name, text)| (home.join(".ssh").join(FRAGMENTS).join(name), text));
        Self {
            account,
            home: home.to_owned(),
            profile,
            fragment,
        }
    }

    fn ssh(&self) -> PathBuf {
        self.home.join(".ssh")
    }

    fn fragments(&self) -> PathBuf {
        self.ssh().join(FRAGMENTS)
    }

    fn client(&self) -> PathBuf {
        self.profile.join(CLIENT_CONFIG)
    }

    fn record(&self) -> PathBuf {
        self.profile.join(CLIENT_RECORD)
    }

    fn config(&self) -> PathBuf {
        self.ssh().join("config")
    }

    fn check_ssh_directory(&self) -> Result<()> {
        self.account.home_directory(&self.home)?;
        self.account.existing_directory(&self.ssh())
    }

    /// Whether the configuration, read as `found`, is a file the install made and may be
    /// removed at all: it is safe, and the profile's unchanged fragment includes it.
    fn check_client(&self, found: &Found) -> Result<()> {
        self.account.profile_directory(&self.profile)?;
        self.account.check_client(&self.client(), found)?;
        let (path, _) = self
            .fragment
            .as_ref()
            .context("no file in massrelay.d can show that the install made it")?;
        self.account
            .read(path)
            .and_then(|fragment| {
                let fragment =
                    fragment.with_context(|| format!("{} is missing", path.display()))?;
                self.check_fragment(&fragment)
            })
            .context("it is not shown to be the install's")
    }

    /// Whether the record, read as `found`, is a private one of exactly `contents`.
    fn check_record(&self, found: &Found, contents: &[u8]) -> Result<()> {
        self.account.profile_directory(&self.profile)?;
        self.account.check_record(&self.record(), found)?;
        ensure!(
            found.contents == format!("{:x}\n", Sha256::digest(contents)).as_bytes(),
            "it is not what {CLIENT_RECORD} says MassRelay last wrote"
        );
        Ok(())
    }

    /// Whether a configuration holding `contents` holds nothing but what MassRelay wrote,
    /// and if so whether the record is of it. An empty one holds nothing to lose.
    fn written(&self, contents: &[u8]) -> Result<bool> {
        let recorded = self.account.read(&self.record()).and_then(|record| {
            let record = record.with_context(|| {
                format!("{CLIENT_RECORD}, which would show what MassRelay wrote, is missing")
            })?;
            self.check_record(&record, contents)
        });
        match recorded {
            Ok(()) => Ok(true),
            Err(_) if contents.is_empty() => Ok(false),
            Err(error) => Err(error),
        }
    }

    /// Remove the configuration, and then a record of it, if what is there now is the
    /// install's and MassRelay's writing. Otherwise keep both and say why. Only to be
    /// called while nothing writes them.
    fn remove_client(&self) -> Result<()> {
        let path = self.client();
        for _ in 0..ATTEMPTS {
            let Some(found) = self.account.read(&path)? else {
                return Ok(());
            };
            let recorded = match self
                .check_client(&found)
                .and_then(|()| self.written(&found.contents))
            {
                Ok(recorded) => recorded,
                Err(reason) => {
                    // The terminal may have gone with the service, which must not stop this.
                    let kept = format!("Kept {}: {reason:#}", path.display());
                    let _ = writeln!(std::io::stdout(), "{}", crate::visible(&kept));
                    return Ok(());
                }
            };
            if self.account.remove(&path, &found)? {
                if recorded {
                    delete(&self.account, &self.record(), |record| {
                        self.check_record(record, &found.contents)
                    })?;
                }
                return Ok(());
            }
        }
        bail!(
            "{} kept changing while it was being removed",
            path.display()
        )
    }

    fn check_fragment(&self, found: &Found) -> Result<()> {
        self.check_ssh_directory()?;
        self.account.existing_directory(&self.fragments())?;
        let (path, text) = self.fragment.as_ref().context("no fragment to check")?;
        self.account.check_fragment(path, found)?;
        ensure!(
            found.contents == text.as_bytes(),
            "{} was changed after massrelay install wrote it",
            path.display()
        );
        Ok(())
    }

    fn check_config(&self, found: &Found) -> Result<()> {
        self.check_ssh_directory()?;
        self.account.check_fragment(&self.config(), found)
    }

    /// Whether the added `Include` would still match a file, not counting `removed`.
    fn included_elsewhere(&self, removed: Option<&Path>) -> Result<bool> {
        let directory = self.fragments();
        let entries = match std::fs::read_dir(&directory) {
            Ok(entries) => entries,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(false),
            Err(error) => {
                return Err(error).with_context(|| format!("read {}", directory.display()));
            }
        };
        for entry in entries {
            let path = entry?.path();
            if path.extension().is_some_and(|ext| ext == "conf") && removed != Some(&path) {
                return Ok(true);
            }
        }
        Ok(false)
    }
}

/// What an uninstall expects to do about the profile's configuration.
enum Client {
    Absent,
    /// Never removed: the file, or the install's claim to it, fails a check.
    Keep(String),
    /// The install's. Whether MassRelay wrote all it holds is decided when it is removed,
    /// once nothing writes it. This is why that does not show now.
    Owned(Option<String>),
}

/// What an uninstall removes of one profile's OpenSSH setup. Shown before it is applied.
pub struct Removal {
    setup: Setup,
    client: Client,
    fragment: Fate,
    include: Fate,
}

/// Read what an uninstall of the profile in `state_dir` would remove, changing nothing.
pub fn plan_uninstall(state_dir: &Path) -> Result<Removal> {
    let account = Account::current()?;
    let home = account.home()?;
    Ok(survey(account, &home, state_dir))
}

/// `plan_uninstall` for the account whose home directory is `home`.
pub(crate) fn survey(account: Account, home: &Path, state_dir: &Path) -> Removal {
    let setup = Setup::new(account, home, state_dir);
    let account = &setup.account;
    let client = match account.read(&setup.client()) {
        Ok(None) => Client::Absent,
        Ok(Some(found)) => match setup.check_client(&found) {
            Ok(()) => Client::Owned(
                setup
                    .written(&found.contents)
                    .err()
                    .map(|reason| format!("{reason:#}")),
            ),
            Err(reason) => Client::Keep(format!("{reason:#}")),
        },
        Err(error) => Client::Keep(format!("{error:#}")),
    };
    let fragment = match &setup.fragment {
        Some((path, _)) => Fate::of(account, path, |found| setup.check_fragment(found)),
        None => Fate::Absent,
    };
    let include = match account.read(&setup.config()) {
        Ok(Some(found)) if without_include(&found.contents).is_some() => {
            let removed = setup
                .fragment
                .as_ref()
                .filter(|_| matches!(fragment, Fate::Remove))
                .map(|(path, _)| path.as_path());
            match setup.included_elsewhere(removed) {
                Ok(true) => Fate::Keep(format!("files that stay in {FRAGMENTS} still need it")),
                Ok(false) => match setup.check_config(&found) {
                    Ok(()) => Fate::Remove,
                    Err(error) => Fate::Keep(format!("{error:#}")),
                },
                Err(error) => Fate::Keep(format!("{error:#}")),
            }
        }
        Ok(_) => Fate::Absent,
        Err(error) => Fate::Keep(format!("{error:#}")),
    };
    Removal {
        setup,
        client,
        fragment,
        include,
    }
}

impl std::fmt::Display for Removal {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let fragment = self.setup.fragment.as_ref().map(|(path, _)| path.clone());
        let mut found = !matches!(self.client, Client::Absent);
        let client = self.setup.client();
        match &self.client {
            Client::Absent => {}
            Client::Keep(reason) => writeln!(f, "keep {}: {reason}", client.display())?,
            Client::Owned(None) => writeln!(
                f,
                "remove, if still only MassRelay's writing once the service has stopped: {}",
                client.display()
            )?,
            Client::Owned(Some(reason)) => writeln!(
                f,
                "keep {}: {reason} (checked again once the service has stopped)",
                client.display()
            )?,
        }
        let record = self.setup.record();
        if record.symlink_metadata().is_ok() {
            match self.client {
                Client::Owned(_) => writeln!(
                    f,
                    "remove only with a {CLIENT_CONFIG} that matches it: {}",
                    record.display()
                )?,
                Client::Absent | Client::Keep(_) => writeln!(f, "keep {}", record.display())?,
            }
            found = true;
        }
        let files = [
            (&self.fragment, fragment, "remove"),
            (
                &self.include,
                Some(self.setup.config()),
                "remove the added MassRelay Include and its comment from",
            ),
        ];
        for (fate, path, removal) in files {
            let Some(path) = path else { continue };
            match fate {
                Fate::Absent => continue,
                Fate::Remove => writeln!(f, "{removal}: {}", path.display())?,
                Fate::Keep(reason) => writeln!(f, "keep {}: {reason}", path.display())?,
            }
            found = true;
        }
        if !found {
            writeln!(f, "nothing to remove")?;
        }
        write!(
            f,
            "keep alias reservations, so an old alias never names another device"
        )
    }
}

impl Removal {
    /// Remove what was shown, checking each file again. Never removes more than that, and
    /// can be planned and applied again after a failure. Call it with the profile's runtime
    /// stopped and kept from starting, so that nothing writes the profile meanwhile.
    pub fn apply(self) -> Result<()> {
        let setup = &self.setup;
        let account = &setup.account;
        let removes = |fate: &Fate| matches!(fate, Fate::Remove);
        let owned = matches!(self.client, Client::Owned(_));
        if !owned && ![&self.fragment, &self.include].into_iter().any(removes) {
            return Ok(());
        }
        // The lock an install holds. It has no use for a directory that is missing or that it
        // would refuse, in which nothing is removed either.
        let fragments = setup.fragments();
        let usable =
            setup.check_ssh_directory().is_ok() && account.existing_directory(&fragments).is_ok();
        let _lock = usable
            .then(|| account.lock(&fragments.join(LOCK)))
            .transpose()?;
        // Before the fragment, which shows that the install made it.
        if owned {
            setup.remove_client()?;
        }
        if removes(&self.fragment)
            && let Some((path, _)) = &setup.fragment
        {
            delete(account, path, |found| setup.check_fragment(found))?;
        }
        // Looked at again under the lock: another profile may have been installed since.
        if removes(&self.include) && !setup.included_elsewhere(None)? {
            let config = setup.config();
            update(account, &config, |found| {
                let Some(found) = found else { return Ok(None) };
                let Some(contents) = without_include(&found.contents) else {
                    return Ok(None);
                };
                setup.check_config(found)?;
                Ok(Some(contents))
            })?;
        }
        Ok(())
    }
}

/// The name and contents of the file that points SSH at a profile's `client` configuration.
fn fragment(client: &Path) -> Result<(String, String)> {
    let text = client
        .to_str()
        .with_context(|| format!("path is not Unicode: {}", client.display()))?;
    #[cfg(windows)]
    let text = &text.replace('\\', "/");
    // OpenSSH expands or globs these in an Include, or ends the argument at them.
    ensure!(
        !text
            .chars()
            .any(|c| c.is_control() || "\"\\%$*?[]{}".contains(c)),
        "OpenSSH cannot include {text}; use a state directory whose path has none of \
         \" \\ % $ * ? [ ] {{ }}"
    );
    Ok((
        format!("{:x}.conf", Sha256::digest(text.as_bytes())),
        format!("{GENERATED}Include \"{text}\"\n"),
    ))
}

#[derive(Debug, PartialEq, Eq)]
enum IncludePosition {
    First,
    Later,
    Absent,
}

/// A managed block must precede other global settings to enforce its host pin.
fn include_position(config: &[u8], ssh: &Path) -> IncludePosition {
    let separators = |text: &str| {
        if cfg!(windows) {
            text.replace('\\', "/")
        } else {
            text.to_owned()
        }
    };
    let absolute = separators(&format!("{}/{PATTERN}", ssh.display()));
    let config = config.strip_prefix(BOM).unwrap_or(config);
    let mut first = true;
    for line in config.split(|&byte| byte == b'\n') {
        let line = String::from_utf8_lossy(line);
        let (keyword, arguments) = directive(&line);
        if keyword.is_empty() || keyword.starts_with('#') {
            continue;
        }
        if keyword.eq_ignore_ascii_case("host") || keyword.eq_ignore_ascii_case("match") {
            break;
        }
        if keyword.eq_ignore_ascii_case("include") {
            for (index, word) in words(arguments).iter().enumerate() {
                let word = separators(word);
                if word == PATTERN || word == format!("~/.ssh/{PATTERN}") || word == absolute {
                    return if first && index == 0 {
                        IncludePosition::First
                    } else {
                        IncludePosition::Later
                    };
                }
            }
        }
        first = false;
    }
    IncludePosition::Absent
}

/// A line's keyword and what follows it, split as OpenSSH splits them.
fn directive(line: &str) -> (&str, &str) {
    let line = line.trim_start();
    let (keyword, rest) = match line.strip_prefix('"') {
        Some(quoted) => quoted.split_once('"').unwrap_or((quoted, "")),
        None => {
            let end = line
                .find(|c: char| c.is_whitespace() || c == '=' || c == '"')
                .unwrap_or(line.len());
            line.split_at(end)
        }
    };
    let rest = rest.trim_start();
    (keyword, rest.strip_prefix('=').unwrap_or(rest))
}

/// The arguments of a line: separated by blanks, optionally quoted, ending at a comment.
fn words(arguments: &str) -> Vec<String> {
    let mut words = Vec::new();
    let mut word: Option<String> = None;
    let mut quote = None;
    for c in arguments.chars() {
        match quote {
            Some(open) if c == open => quote = None,
            None if c == '"' || c == '\'' => {
                quote = Some(c);
                word.get_or_insert_default();
            }
            None if c.is_whitespace() => words.extend(word.take()),
            None if c == '#' && word.is_none() => break,
            _ => word.get_or_insert_default().push(c),
        }
    }
    words.extend(word);
    words
}

/// The configuration with the include ahead of everything in it, which is otherwise unchanged,
/// byte order mark first and in its own line endings.
fn with_include(config: &[u8]) -> Result<Vec<u8>> {
    ensure!(
        !config.contains(&0),
        "it is not plain text (UTF-16 perhaps); save it as UTF-8"
    );
    let (mark, body) = match config.strip_prefix(BOM) {
        Some(body) => (BOM, body),
        None => (&[][..], config),
    };
    let newline = match body.iter().position(|&byte| byte == b'\n') {
        Some(end) if body[..end].ends_with(b"\r") => "\r\n",
        _ => "\n",
    };
    let mut updated = mark.to_vec();
    updated.extend(format!("{MARKER}{newline}Include {PATTERN}{newline}").into_bytes());
    if !body.is_empty() {
        updated.extend_from_slice(newline.as_bytes());
        updated.extend_from_slice(body);
    }
    Ok(updated)
}

/// The configuration without the lines `with_include` added, if they are still as written
/// and still apply to every host. Every other byte is kept. An `Include` without the
/// comment is someone else's.
fn without_include(config: &[u8]) -> Option<Vec<u8>> {
    let body = config.strip_prefix(BOM).unwrap_or(config);
    let mark = &config[..config.len() - body.len()];
    let lines: Vec<&[u8]> = body.split_inclusive(|&byte| byte == b'\n').collect();
    let text = |index: usize| {
        let line: &[u8] = lines.get(index)?;
        let line = line.strip_suffix(b"\n").unwrap_or(line);
        Some(line.strip_suffix(b"\r").unwrap_or(line))
    };
    let include = format!("Include {PATTERN}");
    let mut start = 0;
    loop {
        let line = String::from_utf8_lossy(text(start)?);
        let (keyword, _) = directive(&line);
        if keyword.eq_ignore_ascii_case("host") || keyword.eq_ignore_ascii_case("match") {
            return None;
        }
        if text(start) == Some(MARKER.as_bytes()) && text(start + 1) == Some(include.as_bytes()) {
            break;
        }
        start += 1;
    }
    let mut end = start + 2;
    // At the top, where it was written, the blank line after it was written with it.
    if start == 0 && text(end).is_some_and(<[u8]>::is_empty) {
        end += 1;
    }
    Some([mark, &lines[..start].concat(), &lines[end..].concat()].concat())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn only_an_include_that_applies_to_every_host_counts() {
        let ssh = Path::new("/home/someone/.ssh");
        for present in [
            "Include massrelay.d/*.conf",
            "\u{feff}include=massrelay.d/*.conf\r\n",
            "Include = ~/.ssh/massrelay.d/*.conf\nHost a\n",
            "Include '/home/someone/.ssh/massrelay.d/*.conf'",
            "# Host commented\nInclude massrelay.d/*.conf",
        ] {
            assert_eq!(
                include_position(present.as_bytes(), ssh),
                IncludePosition::First
            );
        }
        for later in [
            "StrictHostKeyChecking no\nInclude massrelay.d/*.conf",
            "Include other massrelay.d/*.conf",
        ] {
            assert_eq!(
                include_position(later.as_bytes(), ssh),
                IncludePosition::Later
            );
        }
        for absent in [
            "",
            "# Include massrelay.d/*.conf",
            "Include other # massrelay.d/*.conf",
            "Include massrelay.d/other.conf",
            "Host a\n  Include massrelay.d/*.conf",
            "\tmatch all\nInclude massrelay.d/*.conf",
            "Host=a\nInclude massrelay.d/*.conf",
            "\"Host\" a\nInclude massrelay.d/*.conf",
        ] {
            assert_eq!(
                include_position(absent.as_bytes(), ssh),
                IncludePosition::Absent
            );
        }
    }

    #[test]
    fn removing_the_include_restores_what_it_was_added_to() -> Result<()> {
        for original in [
            &b""[..],
            b"Host a\n",
            b"\xef\xbb\xbf# caf\xe9\r\nUser a\r\nHost b\r\n  Port 1",
            b"\n\nHost a\n",
            b"Include massrelay.d/*.conf\nHost a\n",
        ] {
            assert_eq!(
                without_include(&with_include(original)?).as_deref(),
                Some(original)
            );
        }
        // Lines added above it since, as another tool might, stay where they are.
        assert_eq!(
            without_include(
                b"Include other\n# Added by massrelay install\nInclude massrelay.d/*.conf\n\nHost a\n"
            )
            .as_deref(),
            Some(&b"Include other\n\nHost a\n"[..])
        );
        for kept in [
            "Include massrelay.d/*.conf\n",
            "# Added by massrelay install\n",
            "# Added by massrelay install\nInclude massrelay.d/*.conf other\n",
            "# Added by massrelay install\n\nInclude massrelay.d/*.conf\n",
            "Host a\n# Added by massrelay install\nInclude massrelay.d/*.conf\n",
            "Match all\n# Added by massrelay install\nInclude massrelay.d/*.conf\n",
        ] {
            assert_eq!(without_include(kept.as_bytes()), None, "{kept:?}");
        }
        Ok(())
    }

    #[test]
    fn adding_the_include_keeps_every_byte_and_the_line_endings() -> Result<()> {
        // Latin-1 in a comment, CRLF and no final newline.
        let original = b"\xef\xbb\xbf# caf\xe9\r\nUser a\r\nHost b\r\n  Port 1";
        let updated = with_include(original)?;
        let added = b"# Added by massrelay install\r\nInclude massrelay.d/*.conf\r\n\r\n";
        assert_eq!(updated, [BOM, added, &original[BOM.len()..]].concat());
        assert_eq!(
            include_position(&updated, Path::new("/h/.ssh")),
            IncludePosition::First
        );
        assert!(!with_include(b"User a\n")?.contains(&b'\r'));
        assert!(with_include(b"\xff\xfeH\0o\0").is_err());
        Ok(())
    }
}

